INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES ('funflow', 'oxytocin', 13, 'Animal Sounds', NULL, 'Make an animal sound, and your partner guesses the animal.', NULL, NULL, NULL);
INSERT INTO card_decks (game_key, deck_key, name, hint, position) VALUES ('funflow', 'groupnight', 'Group Night', 'Best for 4 to 10 or more', 4);
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('funflow', 'groupnight', 0, 'Freeze Frame', NULL, 'Two people act out a little moment. Anyone watching can call Freeze, tap one of them on the shoulder, copy their exact pose, and start a brand new scene from right there.', '["Two people arguing over the last slice of pizza", "A photographer directing an awkward photo", "Someone trying to parallel park"]', NULL, NULL),
  ('funflow', 'groupnight', 1, 'Statue Swap', NULL, 'Everyone freezes in a pose when the timer goes off. The next player walks up, takes over one person''s exact pose, and leads the group into a completely different scene.', '["A team huddle before a big match", "A family posing for a photo", "A queue that has been waiting far too long"]', NULL, NULL),
  ('funflow', 'groupnight', 2, 'Opposite Freeze', NULL, 'Play out a short moment together. The instant someone calls Freeze, the next player steps into the same pose but plays the exact opposite mood: calm becomes panicked, proud becomes embarrassed.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 3, 'Freeze on the Word', NULL, 'Pick a word before you start, like "actually" or "wait". The instant someone says it, call Freeze, tap them out, and begin a new scene from their pose.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 4, 'Machine Freeze', NULL, 'The whole group becomes one slow, moving machine, each person adding a small repeating motion. On Freeze, swap any two people''s spots and switch the machine on again.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 5, 'Freeze and Confess', NULL, 'Act out an everyday moment. When someone calls Freeze, the frozen player says one true, small thing about themselves before the next player takes their pose and runs with it.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 6, 'Twenty Questions, Zero Answers', NULL, 'Two players have a conversation using only questions. The first person to answer, state a fact, or go quiet for too long is out.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 7, 'Interview, Questions Only', NULL, 'One player is interviewed about their day, their dream job or their last trip. Both the interviewer and the guest may only speak in questions.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 8, 'The Waiter Who Only Asks', NULL, 'Act out ordering food at a restaurant, but the customer and the waiter can only ever reply with a question.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 9, 'Question Tag', NULL, 'Stand in a circle. Ask the person next to you a question. They answer with a new question aimed at someone else, and so on, as fast as you can keep it going.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 10, 'A Small Disagreement, Questions Only', NULL, 'Two players argue about something small, like whose turn it is to pick the music, using nothing but questions, getting more dramatic each round.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 11, 'The Check-Up, Questions Only', NULL, 'Act out a visit to the doctor''s. Patient and doctor can only speak in questions, however confusing that gets.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 12, 'Story, A to Z', NULL, 'Tell a group story one sentence at a time. Each new sentence must start with the next letter of the alphabet, starting from A.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 13, 'Introductions, A to Z', NULL, 'Go around the circle. Each person says their name plus one fact about themselves, starting with the next letter of the alphabet.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 14, 'Excuses, A to Z', NULL, 'Take turns giving an excuse for being late, each one starting with the next letter of the alphabet. The silliest excuse wins the round.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 15, 'Compliments, A to Z', NULL, 'Go around the group giving the person next to you a compliment that starts with the next letter of the alphabet.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 16, 'Shopping List, A to Z', NULL, 'Build a shopping list together out loud. Each new item starts with the next letter of the alphabet, and everyone repeats the whole list so far before adding theirs.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 17, 'Weekend Plans, Z to A', NULL, 'Hold a short conversation about your weekend plans where each line starts with the next letter of the alphabet, going backward from Z to A.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 18, 'Scene from a Hat: The Place', NULL, 'Write a place on a scrap of paper (a waiting room, a spaceship, a wedding). Draw one, and two players set a scene there without saying the place out loud.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 19, 'Scene from a Hat: The Problem', NULL, 'Write a small problem on a scrap of paper (the Wi-Fi is down, someone forgot the cake). Draw one and act out how the group solves it.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 20, 'Scene from a Hat: The Relationship', NULL, 'Write a pair of people on a scrap of paper (two rivals, old school friends, a boss and a new hire). Draw one and play out their first thirty seconds together.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 21, 'Scene from a Hat: The Object', NULL, 'Write down an everyday object. Draw one and build a whole scene around someone who is completely obsessed with it.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 22, 'Scene from a Hat: The Strange Event', NULL, 'Write a strange little event on a scrap of paper (the lights keep flickering, a shoe has gone missing). Draw one and improvise how the group reacts.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 23, 'Scene from a Hat: The Job', NULL, 'Write down an unusual job (a professional apologiser, a cloud namer). Draw one and act out their first day at work.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 24, 'Yes, And: Build the Trip', NULL, 'One person starts planning an imaginary trip. Everyone else can only add to it with "Yes, and...", never shutting an idea down.', NULL, NULL, NULL);
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('funflow', 'groupnight', 25, 'Yes, And: Build the Business', NULL, 'Someone pitches a ridiculous business idea. The rest of the group can only reply with "Yes, and..." to grow it, however strange it gets.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 26, 'Yes, And: Build the Excuse', NULL, 'One player starts an excuse for being late. Each person adds to it with "Yes, and..." until the excuse is completely out of hand.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 27, 'Yes, And: Build the Party', NULL, 'Someone describes a party they are throwing. Everyone else keeps adding details with "Yes, and...", making it stranger each round.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 28, 'Yes, And: Build the Gift', NULL, 'One player describes a gift they are giving someone in the group. The rest keep adding to it with "Yes, and..." until it is the strangest gift ever.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 29, 'Yes, And: Build the Rumor', NULL, 'Start a harmless, obviously made-up rumor about a made-up person. Everyone else builds on it with "Yes, and...", each making it more over the top.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 30, 'World''s Worst First Date Line', NULL, 'Take turns giving the worst possible thing to say on a first date. The group decides who wins the title.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 31, 'World''s Worst Way to Explain a Lesson', NULL, 'Take turns acting out the worst possible way to explain a simple lesson to a class.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 32, 'World''s Worst Tour Guide Fact', NULL, 'Take turns giving the worst possible one-line fact about a famous landmark.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 33, 'World''s Worst Thing a Waiter Could Say', NULL, 'Take turns giving the worst possible thing a waiter could say while taking an order.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 34, 'World''s Worst Way to Hand Someone a Gift', NULL, 'Take turns acting out the worst possible way to hand someone a gift.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 35, 'World''s Worst Wedding Speech Opener', NULL, 'Take turns giving the worst possible opening line for a wedding speech.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 36, 'One Word Story: A Holiday', NULL, 'Tell the story of an imaginary holiday, one word at a time, going around the circle. Keep it moving; nobody plans ahead.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 37, 'One Word Story: A Rescue', NULL, 'Tell the story of a daring rescue, one word per person, around the circle, as fast as you can.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 38, 'One Word Story: The New Pet', NULL, 'Tell the story of someone bringing home a very unusual new pet, one word at a time around the group.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 39, 'One Word Story: The Lost Phone', NULL, 'Tell the story of a phone that goes missing and everything that happens trying to find it, one word at a time.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 40, 'One Word Story: The Wrong Party', NULL, 'Tell the story of someone who walks into the wrong party by mistake, one word at a time around the circle.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 41, 'One Word Story: The Time Machine', NULL, 'Tell the story of a homemade time machine that almost works, one word per person, around the group.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 42, 'What Is This, Really?', NULL, 'Pick up any object in the room and mime using it as something completely different. The group calls out guesses until someone gets it.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 43, 'Prop Relay', NULL, 'Mime using an object as one thing, then pass it to the next person, who must mime it as something else entirely.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 44, 'The Object''s Secret Life', NULL, 'Mime an everyday object coming alive with its own tiny personality, no words allowed, until the group names it.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 45, 'Mystery Tool', NULL, 'Mime inventing a brand-new gadget out of an everyday object, and let the group guess what problem it solves.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 46, 'Not What It Looks Like', NULL, 'Pick an object and mime the single strangest possible use for it. The first correct guess passes the object on.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 47, 'Shrink or Grow', NULL, 'Mime an everyday object as if it were either giant-sized or tiny, and let the group guess both the object and its new size.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 48, 'Rollercoaster: The Apology', NULL, 'Replay a short apology scene. Someone outside the scene calls out a new mood every few seconds, like smug, heartbroken or thrilled, and the players switch instantly.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 49, 'Rollercoaster: The Phone Call', NULL, 'Act out answering a phone call. Someone calls out a new mood every few seconds and the caller''s whole tone has to flip right away.', NULL, NULL, NULL);
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('funflow', 'groupnight', 50, 'Rollercoaster: The Surprise', NULL, 'Replay someone opening a surprise gift. A caller shouts a new mood every few seconds, from bored to thrilled to suspicious.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 51, 'Rollercoaster: The Goodbye', NULL, 'Act out saying goodbye at the door. Someone calls out a new mood every few seconds, and the goodbye has to match it instantly.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 52, 'Rollercoaster: The Interview Answer', NULL, 'Replay one answer from a job interview. A caller shouts a new mood every few seconds, from nervous to overconfident to sleepy.', NULL, NULL, NULL),
  ('funflow', 'groupnight', 53, 'Rollercoaster: The Toast', NULL, 'Give a short toast at an imaginary celebration. Someone calls out a new mood every few seconds and the toast has to shift with it.', NULL, NULL, NULL);
