-- FunFlow: fixes the seven rows from migration 0042 whose example lists never made it past the PDF extraction (the bullet
-- glyphs on those pages were not ones build.py's FunFlow parser recognised, so each whole page landed in `text` as one
-- run-on line instead of a clean `list`, every example folded under the next like a layer — the "one option not loading"
-- the founder saw), plus one row (oxytocin 7) where the same parser never saw the page break and left a second card,
-- Animal Sounds, stuck inside Sound Effects Storytelling's own text, so it never surfaced as a card of its own. Restored
-- here from the same seeded text, by hand, since the source PDFs are not kept in the repo.
-- Also adds a new deck, Group Night, for bigger groups (4 to 10 or more people). Group Night is built on the mechanics,
-- never the wording, of well-known improv game formats (Freeze, Questions Only, the Alphabet Game, Scenes from a Hat,
-- Yes And, World's Worst, One Word Story, Props, Emotional Rollercoaster); every card is original text in the app's own
-- house voice, easy and low-stakes, and alcohol-neutral on purpose — no card assumes, needs or rewards drinking, since
-- this app is for wellbeing and relationships, not a drinking game.

UPDATE cards SET text = 'Ask each other, back and forth: would you rather...?', list_json = '["A million dollars, or the ability to speak every language?", "Travel to space, or explore the deepest parts of the ocean?", "Ten minutes of fame, or a lifetime of anonymity?", "Live without the internet, or live without air conditioning?", "Always be ten minutes late, or twenty minutes early?", "Be able to fly, or be invisible?", "Lose your phone forever, or lose the ability to remember names?", "Live a hundred years in the past, or a hundred years in the future?", "Read minds, or be able to teleport?", "Have more time, or more money?", "Always laugh loudly at the wrong moment, or never laugh at all?", "A bad date with good food, or a good date with bad food?", "Always make the first move, or wait forever for someone else to?", "Accidentally text your crush, or accidentally text your boss something embarrassing?", "Always get a text back late, or never get a reply at all?"]' WHERE game_key = 'funflow' AND deck_key = 'oxytocin' AND position = 2;
UPDATE cards SET text = 'Say the first word that comes to mind. Your partner answers with the word it makes them think of.', list_json = '["Ocean → Wave", "Coffee → Mug", "Mountain → Climb", "Pizza → Cheese", "Tree → Forest", "Sky → Cloud", "Sun → Hot", "Book → Read", "Night → Moon", "Rain → Umbrella"]' WHERE game_key = 'funflow' AND deck_key = 'oxytocin' AND position = 4;
UPDATE cards SET text = 'Mimic each movement the leader makes, then add a new one of your own.', list_json = '["Clap twice, then snap fingers", "Pat head and rub stomach", "Spin around and then touch your toes", "Hop on one foot three times", "Wave your hands in the air and jump", "Pretend to fly like a bird", "March in place while humming", "Spin around while clapping hands", "Pretend to throw a basketball", "Mimic swimming motions"]' WHERE game_key = 'funflow' AND deck_key = 'oxytocin' AND position = 6;
UPDATE cards SET text = 'Take turns answering, slowly, and see who tears up first.', list_json = '["What''s the most beautiful thing you have been told?", "When was the last time you cried, and why?", "Is there someone you still think about? What reminds you of them?", "What''s a feeling that you miss?", "Who was your first love, and why did you fall for them?", "What''s your biggest regret?"]' WHERE game_key = 'funflow' AND deck_key = 'oxytocin' AND position = 8;
UPDATE cards SET text = 'Both players say a word at the same time. Then try to say, together, the word that connects your last two.', list_json = '["Sun + Beach → Vacation", "Coffee + Morning → Caffeine", "Rain + Sky → Cloud", "Movie + Popcorn → Cinema", "Car + Road → Trip", "Dog + Park → Walk", "Laptop + Desk → Work", "Tree + Leaf → Nature", "Mountain + Hike → Adventure", "Book + Library → Reading", "Moon + Night → Dreams", "Pizza + Cheese → Delicious", "Guitar + Music → Concert", "Plane + Sky → Travel", "Snow + Winter → Cold", "Pen + Paper → Writing", "Dance + Music → Rhythm", "Camera + Smile → Photo", "Coffee + Cup → Break", "Window + Rain → Calm", "Apple + Tree → Orchard", "Ocean + Wave → Surf", "Butter + Bread → Toast", "Phone + Call → Conversation", "Fire + Heat → Warmth"]' WHERE game_key = 'funflow' AND deck_key = 'serotonin' AND position = 11;
UPDATE cards SET text = 'Name items in a chosen category that start with each letter of the alphabet, in turn.', list_json = '["Animals: Alligator, Bear, Cat, etc.", "Cities: Amsterdam, Berlin, Chicago, etc.", "Fruits: Apple, Banana, Cherry, etc.", "Jobs: Accountant, Banker, Chef, etc.", "Famous brands: Adidas, BMW, Coca-Cola, etc.", "Movies: Avatar, Batman, Casablanca, etc.", "Countries: Argentina, Brazil, Canada, etc.", "Celebrities: Angelina Jolie, Brad Pitt, Cameron Diaz, etc.", "Foods: Avocado, Burger, Carrot, etc.", "TV shows: American Idol, Breaking Bad, Community, etc."]' WHERE game_key = 'funflow' AND deck_key = 'dopamine' AND position = 4;
UPDATE cards SET text = 'Say it three times fast, without tripping over your own tongue.', list_json = '["She sells seashells by the seashore", "Red lorry, yellow lorry, blue lorry, black lorry", "Peter Piper picked a peck of pickled peppers", "Six slippery snails slid slowly seaward", "I saw Susie sitting in a shoeshine shop", "Can you can a can as a canner can can a can?", "Kaccha papad, pakka papad", "A proper copper coffee pot", "Thin sticks, thick bricks stick", "Blue bulb, black bull, blue bull, black bulb", "I saw a kitten eating chicken in the kitchen", "Black bug bleeds black blood", "He threw three free throws", "A snake sneaks to seek a snack", "The big black bug bit the big black bear", "Eleven benevolent elephants", "Four furious friends fought for the phone", "Truly rural. Really leery, rarely Larry", "Sheena leads, Sheila needs. Rory''s lawn", "We surely shall see the sunshine soon", "Unique New York, unique New York", "Three thin thieves thought a thousand thoughts", "Four furious frogs fretted over flies", "A noisy noise annoys an oyster", "Fred fed Ted bread, and Ted fed Fred bread"]' WHERE game_key = 'funflow' AND deck_key = 'dopamine' AND position = 7;
UPDATE cards SET text = 'Tell a story while your partner provides sound effects using only their voice.' WHERE game_key = 'funflow' AND deck_key = 'oxytocin' AND position = 7;

UPDATE card_games SET how_to = 'Pick a deck, draw a card and play what it says. Most games work with 2 or more people, and 2 to 6 is best, except Group Night, made for 4 to 10 or more, perfect for a bigger night in.' WHERE game_key = 'funflow';

